{"id": "attr3", "title": "Several describing words before a noun", "cat": "Describing and comparing", "catOrder": 2, "catBlurb": "Say what something is like, compare things, say how much, and say how well or how completely something is done.", "covers": [73], "formula": [{"t": "Whose / which action + 的", "k": false, "z": true, "sep": ""}, {"t": "这 / 那 + measure word", "k": true, "z": true, "sep": "+"}, {"t": "Adjective (+ 的)", "k": false, "z": true, "sep": "+"}, {"t": "Noun", "k": false, "z": false, "sep": "+"}], "explain": ["When several words describe one noun, they all go before it. A common order is: who it belongs to or what was done to it (+ 的), then 这 / 那 + measure word, then the adjective, then the noun: 我昨天买的那条黑色的裤子 'the black trousers I bought yesterday'. The 这 / 那 + measure word part can also come first: 那条我昨天买的裤子.", "Short adjectives such as 新, 大 and 小 join the noun without 的: 我的新手机 'my new phone'; 一个大蛋糕 'a big cake'.", "Keep the measure word right after 这, 那 or the number: 那条黑色的裤子."], "examples": [{"zh": "我昨天买的那条裤子在哪儿？", "py": "Wǒ zuótiān mǎi de nà tiáo kùzi zài nǎr?", "en": "Where are the trousers I bought yesterday?", "parts": [{"t": "我昨天买的", "c": ""}, {"t": "那", "c": "k"}, {"t": "条", "c": ""}, {"t": "裤子", "c": "thing"}, {"t": "在哪儿？", "c": ""}]}, {"zh": "这是我妈妈做的一个大蛋糕。", "py": "Zhè shì wǒ māma zuò de yí ge dà dàngāo.", "en": "This is a big cake my mom made.", "parts": [{"t": "这是我妈妈做的一个", "c": ""}, {"t": "大", "c": "does"}, {"t": "蛋糕", "c": "thing"}, {"t": "。", "c": ""}]}, {"zh": "那个穿红色衣服的女孩儿是谁？", "py": "Nàge chuān hóngsè yīfu de nǚháir shì shéi?", "en": "Who is that girl in red?", "parts": [{"t": "那", "c": "k"}, {"t": "个穿红色衣服的", "c": ""}, {"t": "女孩儿", "c": "thing"}, {"t": "是谁？", "c": ""}]}, {"zh": "我的新手机很贵。", "py": "Wǒ de xīn shǒujī hěn guì.", "en": "My new phone is expensive.", "parts": [{"t": "我的", "c": ""}, {"t": "新", "c": "does"}, {"t": "手机", "c": "thing"}, {"t": "很贵。", "c": ""}]}], "mistakes": ["The measure word stays with 这 / 那: 那条黑色的裤子, not 那黑色的条裤子.", "Everything that describes the noun goes before it: 穿红色衣服的女孩儿 'the girl in red'."], "q": [{"sentence": {"zh": "我昨天买的那条裤子在哪儿？", "py": "Wǒ zuótiān mǎi de nà tiáo kùzi zài nǎr?", "en": "Where are the trousers I bought yesterday?"}, "explain": "What was done to it + 的, then 那条, then the noun.", "pt": "g3-73", "type": "order", "kicker": "Build it", "prompt": "Put the words in order: Where are the trousers I bought yesterday?", "toks": ["我", "昨天", "买", "的", "那", "条", "裤子", "在", "哪儿"], "reveal": "我昨天买的那条裤子在哪儿？"}, {"sentence": {"zh": "那个穿红色衣服的女孩儿是谁？", "py": "Nàge chuān hóngsè yīfu de nǚháir shì shéi?", "en": "Who is that girl in red?"}, "explain": "The description comes before the noun.", "pt": "g3-73", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: Who is that girl in red?", "options": [{"id": "a", "label": "那个穿红色衣服的女孩儿是谁？"}, {"id": "b", "label": "那个女孩儿穿红色衣服的是谁？"}], "correct": "a", "reveal": "那个穿红色衣服的女孩儿是谁？", "levelOnly": ["那个女孩儿穿红色衣服的是谁？"]}, {"sentence": {"zh": "这是我妈妈做的一个大蛋糕。", "py": "Zhè shì wǒ māma zuò de yí ge dà dàngāo.", "en": "This is a big cake my mom made."}, "explain": "Who made it + 的, then 一个大蛋糕.", "pt": "g3-73", "type": "cloze", "kicker": "Fill it", "prompt": "Type the missing word", "big": "这是我妈妈做___一个大蛋糕。", "sub": "This is a big cake my mom made.", "placeholder": "Pinyin or character", "accepts": ["de", "的"], "reveal": "的 · de"}, {"sentence": {"zh": "我喜欢那条黑色的裤子。", "py": "Wǒ xǐhuan nà tiáo hēisè de kùzi.", "en": "I like that pair of black trousers."}, "explain": "The measure word stays right after 那.", "pt": "g3-73", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: I like that pair of black trousers?", "options": [{"id": "a", "label": "我喜欢那条黑色的裤子。"}, {"id": "b", "label": "我喜欢那黑色的条裤子。"}], "correct": "a", "reveal": "我喜欢那条黑色的裤子。", "levelOnly": ["我喜欢那黑色的条裤子。"]}, {"sentence": {"zh": "我的新手机很贵。", "py": "Wǒ de xīn shǒujī hěn guì.", "en": "My new phone is expensive."}, "explain": "新 joins the noun without 的.", "pt": "g3-73", "type": "order", "kicker": "Build it", "prompt": "Put the words in order: My new phone is expensive.", "toks": ["我", "的", "新", "手机", "很", "贵"], "reveal": "我的新手机很贵。"}], "qx": [{"sentence": {"zh": "那个穿红色衣服的女孩儿是谁？", "py": "Nàge chuān hóngsè yīfu de nǚháir shì shéi?", "en": "Who is that girl in red?"}, "explain": "那个, then the description + 的, then the noun.", "pt": "g3-73", "type": "order", "kicker": "Build it", "prompt": "Put the words in order: Who is that girl in red?", "toks": ["那个", "穿", "红色", "衣服", "的", "女孩儿", "是", "谁"], "reveal": "那个穿红色衣服的女孩儿是谁？"}, {"sentence": {"zh": "我昨天新买的手机丢了。", "py": "Wǒ zuótiān xīn mǎi de shǒujī diū le.", "en": "The new phone I bought yesterday is lost."}, "explain": "The time 昨天 comes before 新买.", "pt": "g3-73", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: The new phone I bought yesterday is lost?", "options": [{"id": "a", "label": "我昨天新买的手机丢了。"}, {"id": "b", "label": "我新昨天买的手机丢了。"}], "correct": "a", "reveal": "我昨天新买的手机丢了。", "levelOnly": ["我新昨天买的手机丢了。"]}, {"sentence": {"zh": "那两个新来的同学是哪国人？", "py": "Nà liǎng ge xīn lái de tóngxué shì nǎ guó rén?", "en": "Which country are those two new classmates from?"}, "explain": "那 + number + measure word, then the description.", "pt": "g3-73", "type": "cloze", "kicker": "Fill it", "prompt": "Type the missing word", "big": "那___个新来的同学是哪国人？", "sub": "Which country are those two new classmates from?", "placeholder": "Pinyin or character", "accepts": ["liang", "两"], "reveal": "两 · liǎng"}, {"sentence": {"zh": "我很喜欢你送给我的那本书。", "py": "Wǒ hěn xǐhuan nǐ sòng gěi wǒ de nà běn shū.", "en": "I really like that book you gave me."}, "explain": "Keep 那本 together.", "pt": "g3-73", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: I really like that book you gave me?", "options": [{"id": "a", "label": "我很喜欢你送给我的那本书。"}, {"id": "b", "label": "我很喜欢那你送给我的本书。"}], "correct": "a", "reveal": "我很喜欢你送给我的那本书。", "levelOnly": ["我很喜欢那你送给我的本书。"]}]},
{"id": "result3", "title": "Results: 到, 住, 走 and 上", "cat": "Doing things to things", "catOrder": 1, "catBlurb": "Move things and say what happens to them or whether the action works out: 把, 被 and 听得懂 / 听不懂.", "covers": [74, 75], "formula": [{"t": "Verb", "k": false, "z": false, "sep": ""}, {"t": "到 / *住 / *走 / *上", "k": true, "z": true, "sep": "+"}], "explain": ["到 after a verb means you reached or got what you were after: 买到 'manage to buy', 找到 'find', 看到 'see', 听到 'hear'. 火车票你买到了没有？ 'Did you manage to get the train tickets?'; 我找到我的手机了 'I have found my phone'. The negative uses 没: 我没买到票 'I did not manage to get a ticket'.", "住 after a verb means it stays put: 记住 'remember (for good)'. 走 after a verb means away: 拿走 'take away', 飞走 'fly away'.", "上 after a verb can mean reaching a goal, often after effort or waiting: 考上大学 'get into university'; 我们终于吃上饭了 'We finally got to eat'; 住上新房子 'get to live in a new home'. 上 can also mark the start of a new state: 爱上 'fall in love with'."], "examples": [{"zh": "火车票你买到了没有？", "py": "Huǒchē piào nǐ mǎi dào le méiyǒu?", "en": "Did you manage to get the train tickets?", "parts": [{"t": "火车票你买", "c": ""}, {"t": "到", "c": "k"}, {"t": "了没有？", "c": ""}]}, {"zh": "请记住这个号码。", "py": "Qǐng jì zhù zhège hàomǎ.", "en": "Please remember this number.", "parts": [{"t": "请记", "c": ""}, {"t": "住", "c": "k"}, {"t": "这个号码。", "c": ""}]}, {"zh": "谁把我的书拿走了？", "py": "Shéi bǎ wǒ de shū ná zǒu le?", "en": "Who took my book away?", "parts": [{"t": "谁把我的书拿", "c": ""}, {"t": "走", "c": "k"}, {"t": "了？", "c": ""}]}, {"zh": "他考上大学了。", "py": "Tā kǎo shàng dàxué le.", "en": "He got into university.", "parts": [{"t": "他考", "c": ""}, {"t": "上", "c": "k"}, {"t": "大学了。", "c": ""}]}], "mistakes": ["For 'did not manage to' use 没 + verb + 到: 我没买到票, not 我不买到票.", "For getting into a school use 考上: 考上大学."], "q": [{"sentence": {"zh": "我找到我的手机了。", "py": "Wǒ zhǎo dào wǒ de shǒujī le.", "en": "I have found my phone."}, "explain": "Verb + 到: you got what you were after.", "pt": "g3-74", "type": "order", "kicker": "Build it", "prompt": "Put the words in order: I have found my phone.", "toks": ["我", "找", "到", "我", "的", "手机", "了"], "reveal": "我找到我的手机了。"}, {"sentence": {"zh": "请记住这个号码。", "py": "Qǐng jì zhù zhège hàomǎ.", "en": "Please remember this number."}, "explain": "记住: remember for good.", "pt": "g3-74", "type": "cloze", "kicker": "Fill it", "prompt": "Type the missing word", "big": "请记___这个号码。", "sub": "Please remember this number.", "placeholder": "Pinyin or character", "accepts": ["zhu", "住"], "reveal": "住 · zhù"}, {"sentence": {"zh": "我没买到票。", "py": "Wǒ méi mǎi dào piào.", "en": "I did not manage to get a ticket."}, "explain": "Use 没 with a result.", "pt": "g3-74", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: I did not manage to get a ticket?", "options": [{"id": "a", "label": "我没买到票。"}, {"id": "b", "label": "我不买到票。"}], "correct": "a", "reveal": "我没买到票。", "levelOnly": ["我不买到票。"]}, {"sentence": {"zh": "谁把我的书拿走了？", "py": "Shéi bǎ wǒ de shū ná zǒu le?", "en": "Who took my book away?"}, "explain": "Verb + 走: away.", "pt": "g3-74", "type": "order", "kicker": "Build it", "prompt": "Put the words in order: Who took my book away?", "toks": ["谁", "把", "我", "的", "书", "拿", "走", "了"], "reveal": "谁把我的书拿走了？"}, {"sentence": {"zh": "他考上大学了。", "py": "Tā kǎo shàng dàxué le.", "en": "He got into university."}, "explain": "考上: pass the exam and get in.", "pt": "g3-75", "type": "cloze", "kicker": "Fill it", "prompt": "Type the missing word", "big": "他考___大学了。", "sub": "He got into university.", "placeholder": "Pinyin or character", "accepts": ["shang", "上"], "reveal": "上 · shàng"}], "qx": [{"sentence": {"zh": "你看到我的笔了吗？", "py": "Nǐ kàn dào wǒ de bǐ le ma?", "en": "Have you seen my pen?"}, "explain": "到 goes right after the verb.", "pt": "g3-74", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: Have you seen my pen?", "options": [{"id": "a", "label": "你看到我的笔了吗？"}, {"id": "b", "label": "你看我的笔到了吗？"}], "correct": "a", "reveal": "你看到我的笔了吗？", "levelOnly": ["你看我的笔到了吗？"]}, {"sentence": {"zh": "小鸟飞走了。", "py": "Xiǎo niǎo fēi zǒu le.", "en": "The little bird flew away."}, "explain": "Verb + 走: away.", "pt": "g3-74", "type": "cloze", "kicker": "Fill it", "prompt": "Type the missing word", "big": "小鸟飞___了。", "sub": "The little bird flew away.", "placeholder": "Pinyin or character", "accepts": ["zou", "走"], "reveal": "走 · zǒu"}, {"sentence": {"zh": "我去买票了，可是没买到。", "py": "Wǒ qù mǎi piào le, kěshì méi mǎi dào.", "en": "I went to buy tickets but did not manage to get any."}, "explain": "没 + verb + 到.", "pt": "g3-74", "type": "order", "kicker": "Build it", "prompt": "Put the words in order: I went to buy tickets but did not manage to get any.", "toks": ["我", "去", "买", "票", "了", "可是", "没", "买", "到"], "reveal": "我去买票了，可是没买到。"}, {"sentence": {"zh": "记住，别迟到！", "py": "Jì zhù, bié chídào!", "en": "Remember, don't be late!"}, "explain": "记住: remember for good.", "pt": "g3-74", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: Remember, don't be late!", "options": [{"id": "a", "label": "记住，别迟到！"}, {"id": "b", "label": "记到，别迟到！"}], "correct": "a", "reveal": "记住，别迟到！", "levelOnly": ["记到，别迟到！"]}, {"sentence": {"zh": "她考上了一个好大学。", "py": "Tā kǎo shàng le yí ge hǎo dàxué.", "en": "She got into a good university."}, "explain": "For getting into a school use 考上.", "pt": "g3-75", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: She got into a good university?", "options": [{"id": "a", "label": "她考上了一个好大学。"}, {"id": "b", "label": "她考到了一个好大学。"}], "correct": "a", "reveal": "她考上了一个好大学。", "levelOnly": ["她考到了一个好大学。"]}, {"sentence": {"zh": "我们终于吃上饭了。", "py": "Wǒmen zhōngyú chī shàng fàn le.", "en": "We finally got to eat."}, "explain": "Verb + 上: finally got to.", "pt": "g3-75", "type": "order", "kicker": "Build it", "prompt": "Put the words in order: We finally got to eat.", "toks": ["我们", "终于", "吃", "上", "饭", "了"], "reveal": "我们终于吃上饭了。"}, {"sentence": {"zh": "他爱上了一个中国女孩儿。", "py": "Tā ài shàng le yí ge Zhōngguó nǚháir.", "en": "He fell in love with a Chinese girl."}, "explain": "爱上: fall in love with.", "pt": "g3-75", "type": "cloze", "kicker": "Fill it", "prompt": "Type the missing word", "big": "他爱___了一个中国女孩儿。", "sub": "He fell in love with a Chinese girl.", "placeholder": "Pinyin or character", "accepts": ["shang", "上"], "reveal": "上 · shàng"}, {"sentence": {"zh": "他们终于住上了新房子。", "py": "Tāmen zhōngyú zhù shàng le xīn fángzi.", "en": "They finally got to live in a new home."}, "explain": "住上: get to live in.", "pt": "g3-75", "type": "mc", "kicker": "Choose", "prompt": "Which sentence says: They finally got to live in a new home?", "options": [{"id": "a", "label": "他们终于住上了新房子。"}, {"id": "b", "label": "他们终于住到了新房子上。"}], "correct": "a", "reveal": "他们终于住上了新房子。", "levelOnly": ["他们终于住到了新房子上。"]}]}
